declare @count int=0;
select @count = count(1) from ( select top 1 uid from dbo.asset group by uid having count(1)>1 ) a
if (exists (select * from sys.indexes where name = 'IX_Asset_uid' and is_unique = 0) and @count = 0) begin if exists (select * from sys.indexes si where name = 'IX_Asset_uid' and object_name(object_id) = 'Asset' and exists (select 1 from sys.objects so where so.object_id = si.object_id and schema_name(so.schema_id) = 'dbo')) begin drop INDEX [IX_Asset_uid] ON [dbo].[Asset]; end if not exists (select * from sys.indexes where name = 'IX_Asset_uid') begin CREATE UNIQUE NONCLUSTERED INDEX [IX_Asset_uid] ON [dbo].[Asset] ([uid] asc) end end

CREATE OR ALTER TRIGGER [dbo].[Asset_AfterUpdate] ON [dbo].[Asset] AFTER UPDATE AS Declare @InsCount int = 0, @DelCount int = 0, @UpdatedBy int = 0;
SET NOCOUNT ON;
select @InsCount = count(1) from inserted I where I.object = 'ReferenceItem'; select @DelCount = count(1) from deleted d where d.object = 'ReferenceItem';
if (@InsCount > 0 and @DelCount>0) begin drop table if exists #insertedAssets; create table #insertedAssets (ObjectType varchar(250), ObjectID int,AssetObjectID bigint, UpdatedBy int); create clustered index IX_TempInsertedFields ON #insertedAssets (ObjectType, ObjectID);
drop table if exists #TempFormattedValue; create table #TempFormattedValue (FieldTypeID Int, [Value] nvarchar(250),FormattedValue nvarchar(Max), UpdatedBy int); create clustered index IX_TempFormattedValue ON #TempFormattedValue (FieldTypeID, [Value]);
insert into #insertedAssets(ObjectType,ObjectID,AssetObjectID,UpdatedBy) select distinct replace(ATT.[Object],'Type',''), ATT.ObjectID, I.ObjectID, i.UpdatedBy from inserted i inner join AssetType ATT on ATT.ID = i.AssetTypeID where i.object = 'ReferenceItem' and exists (select 1 from deleted d where d.id = i.id and i.Code <> d.Code);
if exists( select 1 from Field TF inner join FieldType FT on FT.ID = TF.FieldTypeID inner join #insertedAssets SF on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID where SF.ObjectType = 'ReferenceItem') begin
insert into #TempFormattedValue (FieldTypeID,[Value],FormattedValue,UpdatedBy) select FT.ID, cast(SF.AssetObjectID as nvarchar(250)), utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, SF.AssetObjectID, FT.AllowMultipleValues), SF.UpdatedBy from #insertedAssets SF inner join FieldType FT on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID;
UPDATE TF SET TF.UpdatedBy = TFV.UpdatedBy, TF.UpdatedOn = getutcdate() from Field TF inner join #TempFormattedValue TFV on TF.FieldTypeID = TFV.FieldTypeID cross apply string_split(TF.value,',')Vals where try_cast(Vals.Value as bigint) = TFV.Value; end INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Update', I.Object, I.ObjectID, [queue].WriteIndexXml('', I.[Object], I.ObjectID, coalesce(I.CreatedBy, 0)), I.ID from inserted I where I.Object in('Group');
INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Update', I.Object, I.ObjectID, [queue].WriteIndexXml('', I.[Object], I.ObjectID, coalesce(I.CreatedBy, 0)), I.ID from inserted I where I.AssetTypeID in(select id from assettype att where not exists (select 1 from fieldtype ft where ft.AssetTypeID = att.id) and att.Class = 9) end

changeSet.rollback:
CREATE OR ALTER TRIGGER [dbo].[Asset_AfterUpdate] ON [dbo].[Asset] AFTER UPDATE AS Declare @InsCount int = 0, @DelCount int = 0, @UpdatedBy int = 0;
SET NOCOUNT ON;
select @InsCount = count(1) from inserted I where I.object = 'ReferenceItem'; select @DelCount = count(1) from deleted d where d.object = 'ReferenceItem';
if (@InsCount > 0 and @DelCount>0) begin drop table if exists #insertedAssets; create table #insertedAssets (ObjectType varchar(250), ObjectID int,AssetObjectID bigint, UpdatedBy int); create clustered index IX_TempInsertedFields ON #insertedAssets (ObjectType, ObjectID);
drop table if exists #TempFormattedValue; create table #TempFormattedValue (FieldTypeID Int, [Value] nvarchar(250),FormattedValue nvarchar(Max), UpdatedBy int); create clustered index IX_TempFormattedValue ON #TempFormattedValue (FieldTypeID, [Value]);
insert into #insertedAssets(ObjectType,ObjectID,AssetObjectID,UpdatedBy) select distinct replace(ATT.[Object],'Type',''), ATT.ObjectID, I.ObjectID, i.UpdatedBy from inserted i inner join AssetType ATT on ATT.ID = i.AssetTypeID where i.object = 'ReferenceItem' and exists (select 1 from deleted d where d.id = i.id and i.Code <> d.Code);
if exists( select 1 from Field TF inner join FieldType FT on FT.ID = TF.FieldTypeID inner join #insertedAssets SF on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID and SF.AssetObjectID = try_cast(TF.[value] as bigint) where SF.ObjectType = 'ReferenceItem') begin
insert into #TempFormattedValue (FieldTypeID,[Value],FormattedValue,UpdatedBy) select FT.ID, cast(SF.AssetObjectID as nvarchar(250)), utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, SF.AssetObjectID, FT.AllowMultipleValues), SF.UpdatedBy from #insertedAssets SF inner join FieldType FT on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID;
UPDATE TF SET TF.FormattedValue = TFV.FormattedValue, TF.UpdatedBy = TFV.UpdatedBy, TF.UpdatedOn = getutcdate() from Field TF inner join #TempFormattedValue TFV on TF.FieldTypeID = TFV.FieldTypeID and TFV.[Value] = TF.[Value]; end INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Update', I.Object, I.ObjectID, [queue].WriteIndexXml('', I.[Object], I.ObjectID, coalesce(I.CreatedBy, 0)), I.ID from inserted I where I.Object in('Group');
INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Update', I.Object, I.ObjectID, [queue].WriteIndexXml('', I.[Object], I.ObjectID, coalesce(I.CreatedBy, 0)), I.ID from inserted I where I.AssetTypeID in(select id from assettype att where not exists (select 1 from fieldtype ft where ft.AssetTypeID = att.id) and att.Class = 9) end
